UPDATE answer_sheet
status = #{status}, submit_time = #{submitTime}, submit_type = #{submitType}, subject_answer = #{subjectAnswer}, ai_score = #{aiScore}, manual_score = #{manualScore}, manual_comment = #{manualComment}, final_score = #{finalScore}, pass_flag = #{passFlag}, update_time = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE answer_sheet_item
is_correct = #{isCorrect}, ai_score = #{aiScore}, manual_score = #{manualScore}, manual_comment = #{manualComment}, manual_user_id = #{manualUserId}, manual_time = #{manualTime},
WHERE id = #{id}
